import java.io.*;
import java.util.*;

public class Main {
    // Multisets as value -> count maps.
    static void inc(TreeMap<Long, Integer> set, long v) { set.merge(v, 1, Integer::sum); }

    static void dec(TreeMap<Long, Integer> set, long v) {
        int c = set.get(v);
        if (c == 1) set.remove(v); else set.put(v, c - 1);
    }

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in);
        long x = readLong(in);
        int y = (int) readLong(in);
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = readLong(in);
        // top holds the at most y largest positives in the window (operation 2);
        // rest holds the others, paid with operation 1 (sum restSum).
        TreeMap<Long, Integer> top = new TreeMap<>(), rest = new TreeMap<>();
        int topSize = 0, best = 0, l = 0;
        long restSum = 0;
        for (int r = 0; r < n; r++) {
            long v = a[r];
            if (v != 0) {
                inc(top, v);
                topSize++;
                if (topSize > y) {
                    long m = top.firstKey();
                    dec(top, m);
                    topSize--;
                    inc(rest, m);
                    restSum += m;
                }
            }
            while (restSum > x) {
                long w = a[l++];
                if (w == 0) continue;
                if (rest.containsKey(w)) { dec(rest, w); restSum -= w; continue; }
                dec(top, w);
                topSize--;
                if (!rest.isEmpty()) {
                    long m = rest.lastKey();
                    restSum -= m;
                    dec(rest, m);
                    inc(top, m);
                    topSize++;
                }
            }
            best = Math.max(best, r - l + 1);
        }
        System.out.println(best);
    }

    static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"strconv"
)

// entry is a heap item; it is live only while stamp[i] == s.
type entry struct{ v, i, s int }

// lazyHeap is a min-heap by v, or a max-heap when desc is set.
type lazyHeap struct {
	items []entry
	desc  bool
}

func (h *lazyHeap) Len() int { return len(h.items) }
func (h *lazyHeap) Less(i, j int) bool {
	if h.desc {
		return h.items[i].v > h.items[j].v
	}
	return h.items[i].v < h.items[j].v
}
func (h *lazyHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
func (h *lazyHeap) Push(x any)    { h.items = append(h.items, x.(entry)) }
func (h *lazyHeap) Pop() any {
	x := h.items[len(h.items)-1]
	h.items = h.items[:len(h.items)-1]
	return x
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n, x, y := nextInt(), nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// top holds the at most y largest positives in the window (operation 2);
	// rest holds the others, paid with operation 1 (sum restSum).
	top, rest := &lazyHeap{}, &lazyHeap{desc: true}
	stamp := make([]int, n)
	inTop := make([]bool, n)
	popLive := func(h *lazyHeap) entry {
		for {
			e := heap.Pop(h).(entry)
			if stamp[e.i] == e.s {
				return e
			}
		}
	}
	topSize, restSize, restSum, best, left := 0, 0, 0, 0, 0
	for right, v := range a {
		if v != 0 {
			heap.Push(top, entry{v, right, 0})
			inTop[right] = true
			topSize++
			if topSize > y {
				// Move the smallest of top into rest.
				e := popLive(top)
				stamp[e.i]++
				inTop[e.i] = false
				heap.Push(rest, entry{e.v, e.i, stamp[e.i]})
				topSize--
				restSize++
				restSum += e.v
			}
		}
		for restSum > x {
			w := a[left]
			if w != 0 {
				stamp[left]++ // invalidates its heap entry
				if inTop[left] {
					inTop[left] = false
					topSize--
					if restSize > 0 {
						// Refill top with the largest of rest.
						e := popLive(rest)
						stamp[e.i]++
						inTop[e.i] = true
						heap.Push(top, entry{e.v, e.i, stamp[e.i]})
						topSize++
						restSize--
						restSum -= e.v
					}
				} else {
					restSize--
					restSum -= w
				}
			}
			left++
		}
		best = max(best, right-left+1)
	}
	fmt.Println(best)
}
